/// Where cargo puts this package's finished binaries: the directory of the
/// path cargo hands an integration test for its own package's binary
/// (`CARGO_BIN_EXE_blit`). It was once walked up from the test executable
/// (`<profile>/deps/<test>`), but cargo 1.100 moved test executables to
/// `<profile>/build/<package>/<hash>/out/`: the walk then named a folder
/// holding no binaries, and that folder's name, read below as a
/// cross-target triple, broke the nested daemon build as well.
fn bin_dir() -> PathBuf {
    cli_bin()
        .parent()
        .expect("the blit binary's directory")
        .to_path_buf()
}

pub fn cli_bin() -> PathBuf {
    PathBuf::from(env!("CARGO_BIN_EXE_blit"))
}

/// The per-user folder for a CLI run whose test names none: one under the
/// target directory, never the developer's own — every transfer keeps a
/// job log there (JOB_LOGS jl-2), and its retention would evict theirs.
pub fn isolated_config_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("blit-cli-config")
}

/// `blit`, with [`isolated_config_dir`] as its per-user folder.
pub fn cli_command() -> Command {
    let mut cmd = Command::new(cli_bin());
    cmd.arg("--config-dir").arg(isolated_config_dir());
    cmd
}

pub fn daemon_bin() -> PathBuf {
    bin_dir().join(if cfg!(windows) {
        "blit-daemon.exe"
    } else {
        "blit-daemon"
    })
}

/// Build `blit-daemon` at most once per test binary.
///
/// The build exists because `cargo test -p blit-cli` does not build
/// another package's binary; each test binary triggers it itself so
/// no test depends on suite ordering for the daemon to exist (R16-F1,
/// `docs/reviews/followup_review_2026-05-02.md`). Pre-w9-3 every
/// `TestContext::new()` ran its own nested `cargo build` (~75 per
/// full-suite run), all contending for cargo's build-dir lock — the
/// OnceLock keeps the per-process independence guarantee while paying
/// the subprocess cost once per binary
/// (tests-per-test-cargo-build-subprocess).
pub fn ensure_daemon_built() {
    static DAEMON_BUILT: OnceLock<()> = OnceLock::new();
    DAEMON_BUILT.get_or_init(|| {
        let workspace_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .canonicalize()
            .expect("workspace root");
        let mut build = Command::new("cargo");
        build.current_dir(workspace_root);
        build
            .arg("build")
            .arg("-p")
            .arg("blit-daemon")
            .arg("--bin")
            .arg("blit-daemon");
        // Cross-target layout (target/<triple>/debug): the triple must
        // be passed through or the daemon lands in the wrong directory.
        let maybe_target = bin_dir()
            .parent()
            .and_then(|p| p.file_name())
            .map(|component| component.to_string_lossy().to_string());
        if let Some(triple) = maybe_target {
            if triple != "target" {
                build.arg("--target").arg(triple);
            }
        }
        let output = build.output().expect("invoke cargo build for blit-daemon");
        assert!(
            output.status.success(),
            "cargo build blit-daemon failed:\nstdout:\n{}\nstderr:\n{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    });
}

