        .into_iter()
        .find(|c| !holds(*c))
        .into_iter()
        .collect();
    let other_case = other_cases(&ranges)
        .into_iter()
        .flat_map(|(lo, hi)| lo..=hi)
        .find(|c| !holds(*c));
